function arrCreate2D(x, y, val = 0) {
	let arr = [];
	for (let j = 0; j < y; j++) {
		arr[j] = [];
		for (let i = 0; i < x; i++) {
			arr[j][i] = val;
		}
	}
	return arr;
}
function arrDeepCopy(obj) {
  if (typeof obj == 'object') {
    if (isArray(obj)) {
      const l = obj.length;
      let r = new Array(l);
      for (let i = 0; i < l; i++) {
        r[i] = arrDeepCopy(obj[i]);
      }
      return r;
    } else {
      var r = {};
      r.prototype = obj.prototype;
      for (let k in obj) {
        r[k] = arrDeepCopy(obj[k]);
      }
      return r;
    }
  }
  return obj;
}

